//
// The wire shape is FLAT (not enveloped):
// `{"type": "session.created", "conversation_id": <parent>, "child_session_id": <child>, "agent_id": <agent or None>, "parent_session_id": <parent>, "sequence_number": null}`.
//
// The existing tunneled `function_call` ConversationItem
// (carried inside `OutputItemDoneEvent`) is retained
// for compatibility — clients that don't yet implement the
// "subscribe to child stream" pattern can keep rendering sub-
// agent calls from the parent's persistent history.
type SessionCreatedEvent struct {
	// AgentId Registered agent id the child runs as, e.g. `"agent_xyz"`. `None` is permitted only for legacy spawn paths that did not record an agent id; new code MUST set it.
	AgentId *string `json:"agent_id,omitempty"`

	// ChildSessionId The newly-created child session id, e.g. `"conv_child456"`. Same as `conversation_id` on the child's own stream when consumers pivot to it.
	ChildSessionId string `json:"child_session_id"`

	// ConversationId The PARENT session/conversation id — this event rides the parent's stream, e.g. `"conv_parent123"`.
	ConversationId string `json:"conversation_id"`

	// ParentSessionId Echo of `conversation_id` for consumers that key on a dedicated "parent" field rather than the carrier `conversation_id`. Always equal to `conversation_id`; included for forward-compat with clients that may relay these events across stream boundaries. Category: **transient** (SSE-only). The corresponding durable record of "a child session exists" lives in the conversation store as the child conversation row itself (`parent_conversation_id` foreign key) and the parent's tunneled `function_call` item — reconnecting clients discover children by walking the parent's persisted history, not by replaying this event.
	ParentSessionId *string `json:"parent_session_id,omitempty"`
	SequenceNumber  *int64  `json:"sequence_number,omitempty"`

	// Type Always `"session.created"`.
	Type SessionCreatedEventType `json:"type"`
}

// SessionCreatedEventType Always `"session.created"`.
type SessionCreatedEventType string

// SessionForkRequest Request body for `POST /v1/sessions/{source_id}/fork`.
//
// Creates a deep copy of an existing session's items into a new
// session. All fields are optional.
type SessionForkRequest struct {
	// AgentId Built-in agent to bind the fork to, switching it away from the source's agent/harness (e.g. fork a Claude session into a Codex one, or a Claude-SDK session into Claude Code). When `None`, the fork keeps the source's agent. Must be a built-in agent (one listed by `GET /v1/agents`).
	AgentId *string `json:"agent_id,omitempty"`

	// CodexBypassSandbox Opt-in for the DANGEROUS codex-native full-bypass (`--dangerously-bypass-approvals-and-sandbox`) on the fork. The source's bypass label is ALWAYS dropped on a fork (a bypass-armed source can never silently re-arm its clone), so this is the only way a fork enables it — an explicit, banner-gated opt-in from the dialog, mirroring the new-session approval selector. `True` stamps `omnigent.codex_native.bypass_sandbox` on the fork; `False` / omitted leaves the fork in Codex's normal approval/sandbox stance. Only meaningful for a codex-native target; ignored otherwise.
	CodexBypassSandbox *bool `json:"codex_bypass_sandbox,omitempty"`

	// HostId Id for the fork's new sandbox host, with the same shape, capability gate, label and `409` as a managed create's `host_id`. `None` lets the server mint one. Only valid with `host_type: "managed"`.
	HostId *string `json:"host_id,omitempty"`

	// HostType How the fork's host is obtained — `"external"` (the default: the caller binds one afterwards, via `POST /v1/hosts/{host_id}/runners` from the web dialog or `PATCH /v1/sessions/{id}` from the REPL) or `"managed"` (the server provisions a sandbox host for the fork, the same background launch a `host_type: "managed"` create schedules).
	HostType *SessionForkRequestHostType `json:"host_type,omitempty"`

	// ModelOverride Per-session LLM model override to apply to the fork, e.g. `"claude-opus-4-7"`. **Omitting** the field inherits the source's model (same as today, within the same provider family); an explicit value overrides it, and a clear alias (`"default"`, `"off"`, `"reset"`) resets the fork to the bound agent's default. Validated against a conservative model-id charset. Set by the web fork dialog's model picker.
	ModelOverride *string `json:"model_override,omitempty"`

	// ReasoningEffort Per-session reasoning-effort override to apply to the fork, e.g. `"high"`. **Omitting** the field inherits the source's effort; an explicit value overrides it, and a clear alias (`"default"`, `"off"`, `"reset"`) resets it. Validated against the shared effort vocabulary; provider support is enforced at launch. Set by the web fork dialog's effort picker.
	ReasoningEffort        *string `json:"reasoning_effort,omitempty"`
	SandboxProfileId       *string `json:"sandbox_profile_id,omitempty"`
	SandboxProfileRevision *string `json:"sandbox_profile_revision,omitempty"`

	// SandboxProvider Which configured sandbox provider to provision on `host_type: "managed"` (one of the server's `sandbox_providers`); `None` takes the server's first. Only valid with `host_type: "managed"`.
	SandboxProvider *string `json:"sandbox_provider,omitempty"`
	SideChat        *bool   `json:"side_chat,omitempty"`

	// TerminalLaunchArgs Per-session native-terminal pass-through args to apply to the fork, e.g. `["--permission-mode", "auto"]` (the fork dialog's permission-/approval-mode selector). **Omitting** the field keeps today's behavior — the source's args are carried on a same-agent fork and dropped on an agent switch. A list (including `[]`, which clears them) replaces them wholesale. Bounds (count / length) are validated server-side.
	TerminalLaunchArgs *[]string `json:"terminal_launch_args,omitempty"`

	// Title Title for the forked session. When `None`, the server derives `"Fork of <source_title>"`.
	Title *string `json:"title,omitempty"`

	// UpToResponseId Truncation point for the copied history, e.g. `"resp_abc123"`. When set, only items up to and including the last item of that response are copied — items after it are dropped from the fork. When `None` (default), the full history is copied.
	UpToResponseId *string `json:"up_to_response_id,omitempty"`

	// Workspace Git repository URL (optionally `#<branch>`) the server clones into the fork's sandbox as its working directory, e.g. `"https://github.com/org/repo#release-1.2"`. **Omitting** both workspace fields inherits all repositories the source session recorded, so cloning a sandbox session preserves its checkouts; an explicit value overrides it and an explicit `null` gives the fork an empty sandbox. Only valid with `host_type: "managed"` — an external fork's directory is chosen when it binds a host.
	Workspace *string `json:"workspace,omitempty"`

	// Workspaces Repository URLs (each optionally `#<branch>`) to clone into the fork's sandbox, replacing the source's repositories. Send only when `GET /v1/info` reports `session_fork_workspaces`. Several repositories require a provider with `multi_repo` support. Mutually exclusive with `workspace`; explicitly sending `[]` or `null` gives the fork an empty sandbox. Only valid with `host_type: "managed"`.
	Workspaces *[]string `json:"workspaces,omitempty"`
}

// SessionForkRequestHostType How the fork's host is obtained — `"external"` (the default: the caller binds one afterwards, via `POST /v1/hosts/{host_id}/runners` from the web dialog or `PATCH /v1/sessions/{id}` from the REPL) or `"managed"` (the server provisions a sandbox host for the fork, the same background launch a `host_type: "managed"` create schedules).
type SessionForkRequestHostType string

// SessionGitOptions Git worktree options for `POST /v1/sessions`.
//
// Requires `host_id` to be set (and therefore `workspace`, which
// is interpreted as the source repository directory). Two modes,
// selected by `existing_worktree`:
//
//   - **create** (default): the server creates a git worktree on the
//     host for a new branch and starts the runner in that worktree
//     instead of the picked directory.
//   - **bind** (`existing_worktree=True`): `workspace` already IS a
//     pre-existing worktree; no worktree is created. `branch_name` is
//     recorded as the session's `git_branch` for display and opt-in
//     cleanup, and `base_branch` must not be set.
//
// See designs/SESSION_GIT_WORKTREE.md.
type SessionGitOptions struct {
	// BaseBranch Optional base ref to branch from, e.g. `"main"` or `"origin/main"`. `None` branches from the source repository's current `HEAD`. Create mode only — invalid with `existing_worktree`.
	BaseBranch *string `json:"base_branch,omitempty"`

	// BranchName In create mode, the new branch to create and check out, e.g. `"feature/login"`. In bind mode, the branch already checked out in the existing worktree. Validated against git ref-format rules; invalid names fail with `invalid_input`.
	BranchName string `json:"branch_name"`

	// ExistingBranch When `True`, `branch_name` already exists and the host checks it out into a fresh worktree (the deleted-worktree recreate path) instead of creating a new branch. Create mode only; invalid with `existing_worktree` and with `base_branch` (an existing branch has no base to fork).
	ExistingBranch *bool `json:"existing_branch,omitempty"`

	// ExistingWorktree When `True`, bind to the pre-existing worktree at `workspace` instead of creating one (see above).
	ExistingWorktree *bool `json:"existing_worktree,omitempty"`
}

// SessionHeartbeatEvent Idle-stream keepalive on `GET /v1/sessions/{id}/stream`.
//
// Emitted by the session-stream route on a fixed cadence whenever
// the underlying publish queue has been quiet (no turn in flight,
// no resource events). Distinct from `HeartbeatEvent`
// (`response.heartbeat`), which is per-turn and is driven by
// the runtime workflow while a response is producing output.
//
// Why this exists: the session stream stays open across many turns
// and through idle periods (waiting for the user to type). Without
// a periodic emit, intermediate proxies, OS-level sockets, and the
// client's SSE read-timeout can leave a half-open stream
// undetected for minutes after a network event (laptop sleep,
// Wi-Fi handoff). The heartbeat puts a regular byte on the wire
// so the client's read-timeout and the server's
// `request.is_disconnected()` check both fire promptly.
//
// Consumers MAY ignore the payload entirely (the bytes crossing
// the wire are sufficient). The optional `server_time` mirrors
// `HeartbeatEvent` for symmetry and debugging.
type SessionHeartbeatEvent struct {
	SequenceNumber *int64 `json:"sequence_number,omitempty"`

	// ServerTime ISO 8601 UTC timestamp at emission, e.g. `"2026-05-25T10:30:00Z"`. `None` when the producer chose not to populate it.
	ServerTime *string `json:"server_time,omitempty"`

	// Type Always `"session.heartbeat"`.
	Type SessionHeartbeatEventType `json:"type"`
}

// SessionHeartbeatEventType Always `"session.heartbeat"`.
type SessionHeartbeatEventType string

// SessionInputConsumedEvent A queued input item was materialized into conversation history.
//
// Emitted by `POST /v1/sessions/{id}/events` once per accepted
// input item at the moment it is persisted into conversation
// history (either onto a steered active turn or as the seed item
// of a freshly-started one). Wire shape uses the NESTED envelope:
// `{"type": "session.input.consumed", "data": <SessionInputConsumedPayload>, "sequence_number": null}`.
//
// The event name is **provisional** — it may be renamed in a
// future revision. Consumers should reference
// `SessionInputConsumedEvent` (or its `type` literal)
// rather than hardcoding the wire string.
type SessionInputConsumedEvent struct {
	// Data The decoded queued-item payload — see `SessionInputConsumedPayload`.
	Data           SessionInputConsumedPayload `json:"data"`
	SequenceNumber *int64                      `json:"sequence_number,omitempty"`

	// Type Always `"session.input.consumed"`.
	Type SessionInputConsumedEventType `json:"type"`
}

// SessionInputConsumedEventType Always `"session.input.consumed"`.
type SessionInputConsumedEventType string

// SessionInputConsumedPayload Inner payload of a `SessionInputConsumedEvent`.
//
// Emitted by the sessions route handler at the moment a client
// input is persisted into `conversation_items`. Carries the
// persisted-item shape so clients can render the input (e.g.
// the user's message bubble) at the moment of acceptance.
type SessionInputConsumedPayload struct {
	// ClearedPendingId When this consumed message drains a `omnigent.runtime.pending_inputs` entry (a native- terminal web message round-tripping back from the transcript), the drained entry's id, e.g. `"pending_a1b2c3"`. Lets a client drop the matching optimistic bubble by id instead of by position. `None` for non-native messages and for messages that matched no pending entry (e.g. typed directly in the TUI).
	ClearedPendingId *string `json:"cleared_pending_id,omitempty"`

	// CreatedBy Email of the human actor who posted the item, e.g. `"alice@example.com"`. `None` for agent/tool/system items and single-user mode. Mirrors `ConversationItem.to_api_dict` for live attribution.
	CreatedBy *string `json:"created_by,omitempty"`

	// Data Decoded item payload, e.g. `{"role": "user", "content": [{"type": "input_text", "text": "Hello"}]}`. Heterogeneous and `type`-specific.
	Data map[string]interface{} `json:"data"`

	// ItemId Stable identifier of the conversation item just persisted, e.g. `"item_abc123"`.
	ItemId string `json:"item_id"`

	// Type The item type discriminator — `"message"` for user messages, `"function_call_output"` for tool results, etc. Mirrors `omnigent.server.schemas.SessionEventInput`'s `type` field.
	Type string `json:"type"`
}

